import React, { useState } from "react";
import AddIncome from "./components/AddIncome";
import AddExpense from "./components/AddExpense";
import BalanceCard from "./components/BalanceCard";
import TransactionList from "./components/TransactionList";
import ExpenseChart from "./components/ExpenseChart";

function App() {
  const [transactions, setTransactions] = useState([]);
  const [showChart, setShowChart] = useState(false);
  const [showBalance, setShowBalance] = useState(false);
  const [showForms, setShowForms] = useState(false);

  const addTransaction = (transaction) => {
    setTransactions([...transactions, transaction]);
  };

  return (
    <div style={{ 
      fontFamily: "Arial", 
      padding: "20px", 
      maxWidth: "800px", 
      margin: "auto",
      backgroundColor: '#fff',
      minHeight: '100vh'
    }}>
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '30px',
        padding: '20px',
        borderBottom: '1px solid #eee'
      }}>
        <h1 style={{ 
          color: '#2c3e50',
          margin: 0
        }}>Expense Tracker</h1>
        <div style={{
          display: 'flex',
          gap: '10px'
        }}>
          <button 
            onClick={() => setShowBalance(!showBalance)}
            style={{
              padding: '8px 16px',
              backgroundColor: '#3498db',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            {showBalance ? 'Hide Balance' : 'Show Balance'}
          </button>
          <button 
            onClick={() => setShowChart(!showChart)}
            style={{
              padding: '8px 16px',
              backgroundColor: '#9b59b6',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            {showChart ? 'Close Breakdown' : 'Show Breakdown'}
          </button>
        </div>
      </div>

      {!showForms ? (
        <div style={{
          textAlign: 'center',
          marginTop: '100px'
        }}>
          <h2 style={{
            color: '#2c3e50',
            marginBottom: '30px'
          }}>Welcome to Expense Tracker</h2>
          <p style={{
            color: '#7f8c8d',
            marginBottom: '40px'
          }}>Manage your income and expenses efficiently</p>
          <button
            onClick={() => setShowForms(true)}
            style={{
              padding: '15px 30px',
              backgroundColor: '#2ecc71',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '16px'
            }}
          >
            Get Started
          </button>
        </div>
      ) : (
        <div style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr',
          gap: '20px',
          marginBottom: '20px'
        }}>
          <AddIncome onAdd={addTransaction} />
          <AddExpense onAdd={addTransaction} />
        </div>
      )}

      {showBalance && (
        <>
          <BalanceCard transactions={transactions} />
          <TransactionList transactions={transactions} />
        </>
      )}

      <ExpenseChart transactions={transactions} visible={showChart} />
    </div>
  );
}

export default App;
